const MONTH_NAMES = ["January","February","March","April","May","June","July","August","September","October","November","December"];

function uid(prefix = "id") {
  return `${prefix}_${Date.now().toString(36)}_${Math.random().toString(36).slice(2, 8)}`;
}

function daysInMonth(ym) {
  // ym = "YYYY-MM"
  const [y, m] = ym.split("-").map(Number);
  return new Date(y, m, 0).getDate();
}

function monthLabel(ym) {
  if (!ym) return "";
  const [y, m] = ym.split("-").map(Number);
  return `${MONTH_NAMES[m - 1]} ${y}`;
}

function currentMonth() {
  const d = new Date();
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}`;
}

// True when "ym" (YYYY-MM) has not fully elapsed yet (i.e. it's the current or a future month).
function isMonthInProgress(ym) {
  return (ym || currentMonth()) >= currentMonth();
}

// Default payable days: if the month is already complete, default to the full month.
// If the month is still in progress (an "advance" slip generated before month-end),
// default to the number of days elapsed so far rather than assuming the whole month.
function defaultPayableDays(ym) {
  const total = daysInMonth(ym);
  if (!isMonthInProgress(ym)) return total;
  const today = new Date();
  const [y, m] = ym.split("-").map(Number);
  if (today.getFullYear() === y && today.getMonth() + 1 === m) {
    return Math.min(today.getDate(), total);
  }
  // A future month with no elapsed days yet.
  return 0;
}

function fmtMoney(n) {
  const v = Number(n) || 0;
  return v.toLocaleString("en-IN", { maximumFractionDigits: 2, minimumFractionDigits: 2 });
}

function defaultPaymentDate(ym) {
  // Payment/execution date defaults to today — the date the slip is actually generated.
  const d = new Date();
  return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}-${String(d.getDate()).padStart(2, "0")}`;
}

const NUM_WORDS_ONES = ["", "One", "Two", "Three", "Four", "Five", "Six", "Seven", "Eight", "Nine", "Ten",
  "Eleven", "Twelve", "Thirteen", "Fourteen", "Fifteen", "Sixteen", "Seventeen", "Eighteen", "Nineteen"];
const NUM_WORDS_TENS = ["", "", "Twenty", "Thirty", "Forty", "Fifty", "Sixty", "Seventy", "Eighty", "Ninety"];

function twoDigitWords(n) {
  if (n < 20) return NUM_WORDS_ONES[n];
  const t = Math.floor(n / 10), o = n % 10;
  return NUM_WORDS_TENS[t] + (o ? " " + NUM_WORDS_ONES[o] : "");
}
function threeDigitWords(n) {
  const h = Math.floor(n / 100), r = n % 100;
  return (h ? NUM_WORDS_ONES[h] + " Hundred" + (r ? " " : "") : "") + (r ? twoDigitWords(r) : "");
}
function numberToWordsIndian(num) {
  num = Math.round(Number(num) || 0);
  if (num === 0) return "Zero";
  const crore = Math.floor(num / 10000000); num %= 10000000;
  const lakh = Math.floor(num / 100000); num %= 100000;
  const thousand = Math.floor(num / 1000); num %= 1000;
  const rest = num;
  let parts = [];
  if (crore) parts.push(threeDigitWords(crore) + " Crore");
  if (lakh) parts.push(threeDigitWords(lakh) + " Lakh");
  if (thousand) parts.push(threeDigitWords(thousand) + " Thousand");
  if (rest) parts.push(threeDigitWords(rest));
  return parts.join(" ").replace(/\s+/g, " ").trim();
}
function netPayInWords(amount) {
  const rupees = Math.floor(Number(amount) || 0);
  const paise = Math.round((Number(amount) - rupees) * 100);
  let words = "Rupees " + numberToWordsIndian(rupees);
  if (paise > 0) words += " and " + numberToWordsIndian(paise) + " Paise";
  return words + " Only";
}

function fmtDate(d) {
  if (!d) return "—";
  try {
    const dt = new Date(d);
    if (isNaN(dt.getTime())) return d;
    return dt.toLocaleDateString("en-IN", { day: "2-digit", month: "short", year: "numeric" });
  } catch { return d; }
}

const EARNING_FIELDS = [
  { key: "basic", label: "Basic Salary" },
  { key: "hra", label: "House Rent Allowance (HRA)" },
  { key: "special", label: "Special Allowance" },
  { key: "incentive", label: "Incentive / Bonus" },
  { key: "overtime", label: "Overtime" },
];

const DEDUCTION_FIELDS = [
  { key: "pf", label: "Provident Fund (PF)" },
  { key: "esi", label: "ESI" },
  { key: "pt", label: "Professional Tax (PT)" },
  { key: "tds", label: "TDS" },
  { key: "lwp", label: "Leave Without Pay (LWP)" },
  { key: "advance", label: "Advance / Loan Recovery" },
];

function emptyEmployee() {
  const e = { id: uid("emp"), empId: "", name: "", designation: "", department: "", doj: "", bankAccount: "", ifsc: "", pan: "", uan: "", status: "Active", paymentMode: "Cash" };
  EARNING_FIELDS.forEach(f => e[f.key] = 0);
  DEDUCTION_FIELDS.forEach(f => e[f.key] = 0);
  return e;
}

function computeSlip(employee, record) {
  const total = record?.totalDaysInMonth || daysInMonth(record?.month || currentMonth());
  const payable = record?.payableDays ?? total;
  const factor = total > 0 ? Math.min(payable, total) / total : 0;

  const eOverride = record?.earningsOverride || {};
  const dOverride = record?.deductionsOverride || {};

  const earnings = EARNING_FIELDS.map(f => {
    const full = eOverride[f.key] != null ? Number(eOverride[f.key]) : (Number(employee[f.key]) || 0);
    return { ...f, full, amount: full * factor };
  });
  const deductions = DEDUCTION_FIELDS.map(f => {
    const full = dOverride[f.key] != null ? Number(dOverride[f.key]) : (Number(employee[f.key]) || 0);
    return { ...f, full, amount: full * factor };
  });

  const grossEarnings = earnings.reduce((s, e) => s + e.amount, 0);
  const totalDeductions = deductions.reduce((s, d) => s + d.amount, 0);
  const netPay = grossEarnings - totalDeductions;

  return { earnings, deductions, grossEarnings, totalDeductions, netPay, factor, total, payable };
}

/* ---------------------------------------------------------------- */
/* Slip numbering                                                     */
/* ---------------------------------------------------------------- */

function companyPrefix(name) {
  const p = (name || "VAW").trim().split(/\s+/).map(w => w[0]).join("").toUpperCase().slice(0, 4);
  return p || "VAW";
}

function slipNoFor(prefix, month, seq) {
  const [yyyy, mm] = (month || currentMonth()).split("-");
  return `${prefix}-SS-${mm}-${yyyy}-${String(seq).padStart(4, "0")}`;
}

