const DEFAULT_SETTINGS = {
  companyName: "Vedank Ayurveda Wellness",
  companyAddress: "A-27, A Block, Sector Institutional Green, LAK 6%, Opposite Referral Hospital (CISF), Greater Noida, G.B Nagar, UP, 201306",
  companyPhone: "+91-9211843023",
  companyEmail: "vedankayurvedawellness@gmail.com",
  gstNo: "09MMWPS5441R1ZE",
  currency: "INR",
  companyLogo: LOGO_DATA_URI,
  password: null,
  nextSlipSeq: 1,
};

function buildSeedRecords(companyName) {
  const prefix = companyPrefix(companyName);
  const sorted = [...SEED_RECORDS_RAW].sort((a, b) => a.month === b.month ? a.empId.localeCompare(b.empId) : a.month.localeCompare(b.month));
  let seq = 1;
  const records = sorted.map(r => {
    const total = daysInMonth(r.month);
    const slipNo = slipNoFor(prefix, r.month, seq);
    seq += 1;
    return {
      id: uid("rec"),
      empId: r.empId,
      month: r.month,
      totalDaysInMonth: total,
      payableDays: total,
      leavesTaken: 0,
      paymentDate: defaultPaymentDate(r.month),
      paymentMode: "Cash",
      status: "Paid",
      pastImport: true,
      slipNo,
      earningsOverride: EARNING_FIELDS.reduce((acc, f) => { acc[f.key] = f.key === "basic" ? (Number(r.salary) || 0) : 0; return acc; }, {}),
      deductionsOverride: DEDUCTION_FIELDS.reduce((acc, f) => { acc[f.key] = 0; return acc; }, {}),
      generatedAt: new Date().toISOString(),
    };
  });
  return { records, nextSeq: seq };
}

/* ---------------------------------------------------------------- */
/* Storage layer                                                     */
/* ---------------------------------------------------------------- */

const LS_PREFIX = "vaw_salary_app:";

// In-memory polyfill: this environment doesn't support browser storage APIs,
// so data persists only for the current session (resets on refresh).
const __memoryStore = {};

async function storeGet(key, fallback) {
  try {
    const raw = __memoryStore[LS_PREFIX + key];
    return raw != null ? JSON.parse(raw) : fallback;
  } catch {
    return fallback;
  }
}
async function storeSet(key, value) {
  try {
    __memoryStore[LS_PREFIX + key] = JSON.stringify(value);
    return true;
  } catch {
    return false;
  }
}

/* ---------------------------------------------------------------- */
/* Root App                                                          */
/* ---------------------------------------------------------------- */

export default function App() {
  const [booting, setBooting] = useState(true);
  const [settings, setSettings] = useState(null);
  const [authed, setAuthed] = useState(false);
  const [employees, setEmployees] = useState([]);
  const [records, setRecords] = useState([]);
  const [attendanceLog, setAttendanceLog] = useState([]);
  const [page, setPage] = useState("dashboard");
  const [toast, setToast] = useState(null);

  // NEW: mode and current employee for employee portal
  const [mode, setMode] = useState("admin"); // "admin" | "employee"
  const [currentEmployeeId, setCurrentEmployeeId] = useState(null);

  const currentEmployee =
    currentEmployeeId && employees.length
      ? employees.find((e) => e.id === currentEmployeeId) || null
      : null;

  

  useEffect(() => {
    (async () => {
      let s = await storeGet("settings", null);
      let emps = await storeGet("employees", []);
      let recs = await storeGet("records", []);
      let log = await storeGet("attendanceLog", []);

      if (emps.length === 0 && recs.length === 0) {
        emps = SEED_EMPLOYEES.map(e => ({ ...e }));
        const seeded = buildSeedRecords(DEFAULT_SETTINGS.companyName);
        recs = seeded.records;
        await storeSet("employees", emps);
        await storeSet("records", recs);
        s = s ? { ...s, nextSlipSeq: Math.max(s.nextSlipSeq || 1, seeded.nextSeq) }
              : { ...DEFAULT_SETTINGS, nextSlipSeq: seeded.nextSeq };
        await storeSet("settings", s);
      }

      if (s) {
        const patched = {
          ...s,
          companyAddress: s.companyAddress || DEFAULT_SETTINGS.companyAddress,
          companyPhone: s.companyPhone || DEFAULT_SETTINGS.companyPhone,
          companyEmail: s.companyEmail || DEFAULT_SETTINGS.companyEmail,
          companyLogo: s.companyLogo || DEFAULT_SETTINGS.companyLogo,
        };
        if (JSON.stringify(patched) !== JSON.stringify(s)) {
          s = patched;
          await storeSet("settings", s);
        }
      }

      // One-time repair for records saved by an older version of this app: a partial
      // earnings/deductions override (e.g. only "basic" pinned) let other fields leak in
      // live from the employee master and inflate totals. Fill any missing keys with 0
      // so an existing override always represents the complete snapshot it was meant to.
      let recsFixed = false;
      recs = recs.map(r => {
        let rec = r;
        if (rec.earningsOverride && Object.keys(rec.earningsOverride).length > 0) {
          const filled = { ...rec.earningsOverride };
          let changed = false;
          EARNING_FIELDS.forEach(f => { if (filled[f.key] == null) { filled[f.key] = 0; changed = true; } });
          if (changed) { rec = { ...rec, earningsOverride: filled }; recsFixed = true; }
        }
        if (rec.deductionsOverride && Object.keys(rec.deductionsOverride).length > 0) {
          const filled = { ...rec.deductionsOverride };
          let changed = false;
          DEDUCTION_FIELDS.forEach(f => { if (filled[f.key] == null) { filled[f.key] = 0; changed = true; } });
          if (changed) { rec = { ...rec, deductionsOverride: filled }; recsFixed = true; }
        }
        return rec;
      });
      if (recsFixed) await storeSet("records", recs);

      setSettings(s);
      setEmployees(emps);
      setRecords(recs);
      setAttendanceLog(Array.isArray(log) ? log : []);
      setBooting(false);
    })();
  }, []);

  async function bumpSlipSeq(newSeq) {
    const next = { ...settings, nextSlipSeq: newSeq };
    setSettings(next);
    await storeSet("settings", next);
  }

  function showToast(msg, kind = "ok") {
    setToast({ msg, kind, key: Date.now() });
    setTimeout(() => setToast(null), 2600);
  }

  async function persistEmployees(next) {
    setEmployees(next);
    await storeSet("employees", next);
  }
  async function persistRecords(next) {
    setRecords(next);
    await storeSet("records", next);
  }
  async function persistSettings(next) {
    setSettings(next);
    await storeSet("settings", next);
  }
  async function persistAttendanceLog(next) {
    setAttendanceLog(next);
    await storeSet("attendanceLog", next);
  }

   if (booting) {
    return (
      <Shell>
        <div className="boot">Loading ledger…</div>
      </Shell>
    );
  }

  // Employee mode is independent of the admin password gate: once an employee
  // has entered a valid Employee ID, show their portal regardless of `authed`
  // (which only ever applies to the admin side).
  if (mode === "employee") {
    if (!currentEmployee) {
      return (
        <Shell>
          <EmployeeLogin
            employees={employees}
            onLogin={(empId) => {
              setCurrentEmployeeId(empId);
            }}
            onBack={() => {
              setMode("admin");
              setCurrentEmployeeId(null);
            }}
          />
        </Shell>
      );
    }
    // fall through to the employee portal shell below
  } else if (!authed) {
    // Default: admin login
    return (
      <Shell>
        <AuthGate
          settings={settings}
          onSetup={async (s) => {
            await persistSettings(s);
            setAuthed(true);
          }}
          onLogin={() => setAuthed(true)}
          onEmployeeMode={() => setMode("employee")}
        />
      </Shell>
    );
  }
  // Employee portal main shell
  if (mode === "employee" && currentEmployee) {
    return (
      <Shell>
        <div className="app-shell">
          <aside className="sidebar no-print">
            <div className="sidebar-brand">
              <div className="brand-mark">
                <div />
              </div>
              <div>
                <div className="brand-name">
                  {currentEmployee.name || "Employee"} Portal
                </div>
                <div className="brand-sub">
                  {settings?.companyName || "Payroll Ledger"}
                </div>
              </div>
            </div>
            <nav className="nav">
              <button
                className={
                  page === "employee-home" ? "nav-item nav-item-active" : "nav-item"
                }
                onClick={() => setPage("employee-home")}
              >
                <LayoutDashboard size={17} strokeWidth={1.8} />
                <span>Overview</span>
              </button>
              <button
                className={
                  page === "employee-attendance"
                    ? "nav-item nav-item-active"
                    : "nav-item"
                }
                onClick={() => setPage("employee-attendance")}
              >
                <CalendarCheck size={17} strokeWidth={1.8} />
                <span>My attendance</span>
              </button>
              <button
                className={
                  page === "employee-slips" ? "nav-item nav-item-active" : "nav-item"
                }
                onClick={() => setPage("employee-slips")}
              >
                <FileText size={17} strokeWidth={1.8} />
                <span>My salary slips</span>
              </button>
              <button
                className={
                  page === "employee-requests"
                    ? "nav-item nav-item-active"
                    : "nav-item"
                }
                onClick={() => setPage("employee-requests")}
              >
                <Upload size={17} strokeWidth={1.8} />
                <span>Requests</span>
              </button>
              <button
                className="nav-item nav-logout"
                onClick={() => {
                  setMode("admin");
                  setCurrentEmployeeId(null);
                  setPage("dashboard");
                }}
              >
                <LogOut size={17} strokeWidth={1.8} />
                <span>Log out</span>
              </button>
            </nav>
          </aside>

            <main className="main-area">
            {page === "employee-home" && (
              <EmployeeHome
                employee={currentEmployee}
                records={records}
                onNavigate={setPage}
              />
            )}

            {page === "employee-attendance" && (
              <EmployeeAttendancePage
                employee={currentEmployee}
                attendanceLog={attendanceLog}
                setAttendanceLog={persistAttendanceLog}
                showToast={showToast}
              />
            )}

            {/* We’ll add employee-slips, employee-requests later */}
          </main>
        </div>
        {toast && (
          <div className={`toast toast-${toast.kind}`} key={toast.key}>
            {toast.msg}
          </div>
        )}
      </Shell>
    );
  }
  return (
    <Shell>
      <div className="app-shell">
        <Sidebar page={page} setPage={setPage} onLogout={() => setAuthed(false)} companyName={settings?.companyName} />
        <main className="main-area">
          {page === "dashboard" && <Dashboard employees={employees} records={records} setPage={setPage} />}
          {page === "employees" && <EmployeesPage employees={employees} setEmployees={persistEmployees} showToast={showToast} />}
          {page === "attendance" && <AttendancePage employees={employees} records={records} setRecords={persistRecords} showToast={showToast} />}
          {page === "attendance-log" && <AttendanceLogPage employees={employees} attendanceLog={attendanceLog} />}
          {page === "slips" && <SlipsPage employees={employees} records={records} setRecords={persistRecords} settings={settings} bumpSlipSeq={bumpSlipSeq} showToast={showToast} />}
          {page === "bulk" && <BulkPage employees={employees} records={records} setRecords={persistRecords} settings={settings} bumpSlipSeq={bumpSlipSeq} showToast={showToast} />}
          {page === "import" && <ImportPage employees={employees} records={records} setRecords={persistRecords} settings={settings} bumpSlipSeq={bumpSlipSeq} showToast={showToast} />}
          {page === "register" && <RegisterPage employees={employees} records={records} settings={settings} />}
          {page === "settings" && <SettingsPage settings={settings} setSettings={persistSettings} employees={employees} records={records} setEmployees={persistEmployees} setRecords={persistRecords} showToast={showToast} />}
        </main>
      </div>
      {toast && <div className={`toast toast-${toast.kind}`} key={toast.key}>{toast.msg}</div>}
    </Shell>
  );
}

/* ---------------------------------------------------------------- */
/* Shell / Theme                                                     */
/* ---------------------------------------------------------------- */

function Shell({ children }) {
  return (
    <div className="ledger-root">
      <style>{CSS}</style>
      {children}
    </div>
  );
}

/* ---------------------------------------------------------------- */
/* Auth                                                               */
/* ---------------------------------------------------------------- */

function AuthGate({ settings, onSetup, onLogin, onEmployeeMode }) {
  const [companyName, setCompanyName] = useState(settings?.companyName || "");
  const [pw, setPw] = useState("");
  const [pw2, setPw2] = useState("");
  const [err, setErr] = useState("");
  const [showReset, setShowReset] = useState(false);
  const [resetConfirm, setResetConfirm] = useState("");

  if (!settings || !settings.password) {
    return (
      <div className="auth-wrap no-print">
        <div className="auth-card">
          <div className="stamp stamp-static">SETUP</div>
          <h1 className="auth-title">Open the Ledger</h1>
          <p className="auth-sub">
            Set up your company and an admin password to secure this payroll ledger on this device.
          </p>
          <label className="field-label">Company name</label>
          <input
            className="input"
            value={companyName}
            onChange={(e) => setCompanyName(e.target.value)}
            placeholder="e.g. Sundar Traders Pvt. Ltd."
          />
          <label className="field-label">Admin password</label>
          <input
            className="input"
            type="password"
            value={pw}
            onChange={(e) => setPw(e.target.value)}
            placeholder="Choose a password"
          />
          <label className="field-label">Confirm password</label>
          <input
            className="input"
            type="password"
            value={pw2}
            onChange={(e) => setPw2(e.target.value)}
            placeholder="Re-enter password"
          />
          {err && (
            <div className="auth-err">
              <AlertTriangle size={14} /> {err}
            </div>
          )}
          <button
            className="btn btn-primary btn-block"
            onClick={() => {
              if (!companyName.trim()) return setErr("Enter a company name.");
              if (pw.length < 4) return setErr("Password should be at least 4 characters.");
              if (pw !== pw2) return setErr("Passwords do not match.");
              onSetup({
                ...settings,
                companyName: companyName.trim(),
                currency: settings?.currency || "INR",
                password: pw,
              });
            }}
          >
            Create ledger
          </button>
          <p className="auth-note">
            Note: this password locks the app on this browser/device only — it isn't a secure multi-user login system.
          </p>
          {onEmployeeMode && (
            <button
              type="button"
              className="btn btn-ghost btn-block"
              style={{ marginTop: 10 }}
              onClick={onEmployeeMode}
            >
              <CalendarCheck size={15} /> I'm an employee — Check in / Check out
            </button>
          )}
        </div>
      </div>
    );
  }

  return (
    <div className="auth-wrap no-print">
      <div className="auth-card">
        <div className="stamp stamp-static">LOCKED</div>
        <h1 className="auth-title">{settings.companyName}</h1>
        <p className="auth-sub">Enter the admin password to open the payroll ledger.</p>
        <label className="field-label">Password</label>
        <input
          className="input"
          type="password"
          value={pw}
          autoFocus
          onChange={(e) => setPw(e.target.value)}
          onKeyDown={(e) => {
            if (e.key === "Enter") {
              if (pw === settings.password) onLogin();
              else setErr("Incorrect password.");
            }
          }}
          placeholder="Password"
        />
        {err && (
          <div className="auth-err">
            <AlertTriangle size={14} /> {err}
          </div>
        )}
        <button
          className="btn btn-primary btn-block"
          onClick={() => {
            if (pw === settings.password) onLogin();
            else setErr("Incorrect password.");
          }}
        >
          <Lock size={15} /> Unlock
        </button>

        {onEmployeeMode && (
          <button
            type="button"
            className="btn btn-ghost btn-block"
            style={{ marginTop: 10 }}
            onClick={onEmployeeMode}
          >
            <CalendarCheck size={15} /> I'm an employee — Check in / Check out
          </button>
        )}

        {!showReset ? (
          <button
            type="button"
            className="btn btn-plain-link"
            style={{ marginTop: 14 }}
            onClick={() => setShowReset(true)}
          >
            Forgot admin password?
          </button>
        ) : (
          <div className="auth-reset-box">
            <p className="auth-note">
              This is a one-way local reset: it clears the payroll data stored in this browser
              (employees, attendance and slips) and lets you set up a fresh admin password.
              It cannot recover the old password. If your data also lives in another browser/
              device, open it there instead.
            </p>
            <label className="field-label">Type RESET to confirm</label>
            <input
              className="input"
              value={resetConfirm}
              onChange={(e) => setResetConfirm(e.target.value)}
              placeholder="RESET"
            />
            <div className="row-gap" style={{ marginTop: 10 }}>
              <button
                type="button"
                className="btn btn-danger"
                disabled={resetConfirm.trim().toUpperCase() !== "RESET"}
                onClick={async () => {
                  try {
                    Object.keys(__memoryStore)
                      .filter((k) => k.startsWith(LS_PREFIX))
                      .forEach((k) => delete __memoryStore[k]);
                  } catch {
                    // ignore
                  }
                  window.location.reload();
                }}
              >
                <AlertTriangle size={15} /> Erase &amp; reset this device
              </button>
              <button
                type="button"
                className="btn btn-ghost"
                onClick={() => {
                  setShowReset(false);
                  setResetConfirm("");
                }}
              >
                Cancel
              </button>
            </div>
          </div>
        )}
      </div>
    </div>
  );
}

function EmployeeLogin({ employees, onLogin, onBack }) {
  const [empCode, setEmpCode] = useState("");
  const [err, setErr] = useState("");

  function submit() {
    const code = empCode.trim().toLowerCase();
    if (!code) {
      setErr("Enter your Employee ID.");
      return;
    }
    const emp =
      employees.find(
        (e) =>
          (e.empId && e.empId.toLowerCase() === code) ||
          (e.id && e.id.toLowerCase() === code)
      ) || null;

    if (!emp) {
      setErr("No employee found with that ID.");
      return;
    }

    if (emp.status === "Inactive") {
      setErr("This employee is marked inactive. Contact admin.");
      return;
    }

    onLogin(emp.id);
  }

  return (
    <div className="auth-wrap no-print">
      <div className="auth-card">
        <div className="stamp stamp-static stamp-amber">EMPLOYEE</div>
        <h1 className="auth-title">Employee portal</h1>
        <p className="auth-sub">
          Enter your Employee ID to open your attendance and salary slip portal.
        </p>

        <label className="field-label">Employee ID</label>
        <input
          className="input"
          value={empCode}
          onChange={(e) => setEmpCode(e.target.value)}
          placeholder="e.g. VAW-GN-005"
        />

        {err && (
          <div className="auth-err">
            <AlertTriangle size={14} /> {err}
          </div>
        )}

        <button className="btn btn-primary btn-block" onClick={submit}>
          <Check size={16} /> Continue
        </button>

        <p className="auth-note">
          Use the Employee ID printed on your salary slips. For login issues,
          contact the payroll admin.
        </p>

        <button
          className="btn btn-ghost btn-block"
          style={{ marginTop: 10 }}
          onClick={onBack}
        >
          <Lock size={14} /> Back to admin login
        </button>
      </div>
    </div>
  );
}
  
