function EmployeesPage({ employees, setEmployees, showToast }) {
  const [editing, setEditing] = useState(null); // employee object or null
  const [query, setQuery] = useState("");
  const [confirmDelete, setConfirmDelete] = useState(null);

  const filtered = employees.filter((e) => {
    const q = query.toLowerCase();
    if (!q) return true;
    return (
      (e.name || "").toLowerCase().includes(q) ||
      (e.empId || "").toLowerCase().includes(q) ||
      (e.designation || "").toLowerCase().includes(q) ||
      (e.department || "").toLowerCase().includes(q)
    );
  });

  function save(emp) {
    const exists = employees.some((e) => e.id === emp.id);
    const next = exists
      ? employees.map((e) => (e.id === emp.id ? emp : e))
      : [...employees, emp];

    setEmployees(next);
    setEditing(null);
    showToast(exists ? "Employee updated." : "Employee added.");
  }

  function remove(id) {
    setEmployees(employees.filter((e) => e.id !== id));
    setConfirmDelete(null);
    showToast("Employee removed.");
  }

  return (
    <div className="page">
      <PageHeader
        eyebrow="Employee Database"
        title="Employees"
        subtitle={`${employees.length} on record`}
        right={
          <button className="btn btn-primary" onClick={() => setEditing(emptyEmployee())}>
            <Plus size={16} /> Add employee
          </button>
        }
      />

      <div className="toolbar">
        <div className="search-box">
          <Search size={15} />
          <input
            placeholder="Search by name, ID, department"
            value={query}
            onChange={(e) => setQuery(e.target.value)}
          />
        </div>
      </div>

      {filtered.length === 0 ? (
        <EmptyState
          text={
            employees.length === 0
              ? "No employees yet. Add your first employee to begin."
              : "No employees match your search."
          }
        />
      ) : (
        <table className="ledger-table">
          <thead>
            <tr>
              <th>ID</th>
              <th>Name</th>
              <th>Designation</th>
              <th>Department</th>
              <th>Monthly Basic</th>
              <th>Status</th>
              <th />
            </tr>
          </thead>
          <tbody>
            {filtered.map((e) => (
              <tr key={e.id}>
                <td className="mono">{e.empId}</td>
                <td>{e.name}</td>
                <td>{e.designation}</td>
                <td>{e.department}</td>
                <td className="mono">{fmtMoney(e.basic)}</td>
                <td>
                  <span className={e.status === "Active" ? "tag tag-green" : "tag tag-muted"}>
                    {e.status}
                  </span>
                </td>
                <td className="row-actions">
                  <button className="icon-btn" onClick={() => setEditing(e)}>
                    <Pencil size={15} />
                  </button>
                  <button
                    className="icon-btn icon-btn-danger"
                    onClick={() => setConfirmDelete(e)}
                  >
                    <Trash2 size={15} />
                  </button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      )}

      {editing && (
        <EmployeeModal
          employee={editing}
          onClose={() => setEditing(null)}
          onSave={save}
        />
      )}

      {confirmDelete && (
        <ConfirmModal
          title="Remove employee?"
          body={`This removes ${confirmDelete.name} from the database. Previously generated salary slips are kept in records.`}
          onCancel={() => setConfirmDelete(null)}
          onConfirm={() => remove(confirmDelete.id)}
        />
      )}
    </div>
  );
}
