function EmployeeAttendancePage({ employee, attendanceLog, setAttendanceLog, showToast }) {
  const today = useMemo(() => new Date().toISOString().slice(0, 10), []); // YYYY-MM-DD

  const punch =
    attendanceLog.find((p) => p.empId === employee.id && p.date === today) || null;

  function nowTime() {
    return new Date().toLocaleTimeString("en-IN", {
      hour: "2-digit",
      minute: "2-digit",
    });
  }

  function doCheckIn() {
    if (punch && punch.checkIn) {
      showToast("Already checked in today.", "ok");
      return;
    }
    const now = nowTime();
    let next;
    if (punch) {
      next = attendanceLog.map((p) => (p.id === punch.id ? { ...p, checkIn: now } : p));
    } else {
      next = [
        ...attendanceLog,
        { id: uid("att"), empId: employee.id, date: today, checkIn: now, checkOut: null },
      ];
    }
    setAttendanceLog(next);
    showToast("Check-in recorded.", "ok");
  }

  function doCheckOut() {
    if (!punch || !punch.checkIn) {
      showToast("Check-in first before check-out.", "ok");
      return;
    }
    if (punch.checkOut) {
      showToast("Already checked out today.", "ok");
      return;
    }
    const now = nowTime();
    const next = attendanceLog.map((p) =>
      p.id === punch.id ? { ...p, checkOut: now } : p
    );
    setAttendanceLog(next);
    showToast("Check-out recorded.", "ok");
  }

  const history = attendanceLog
    .filter((p) => p.empId === employee.id)
    .slice()
    .sort((a, b) => b.date.localeCompare(a.date))
    .slice(0, 14);

  return (
    <div className="page">
      <PageHeader
        eyebrow="Employee portal"
        title="My attendance"
        subtitle={`For ${fmtDate(today)} — ${employee.name}`}
      />

      <div className="panel">
        <div className="panel-head">
          <h3>Today&apos;s punches</h3>
        </div>
        <div className="form-grid form-grid-1">
          <div className="field">
            <span className="field-label">Check-in time</span>
            <div className="mono">{(punch && punch.checkIn) || "Not yet"}</div>
          </div>
          <div className="field">
            <span className="field-label">Check-out time</span>
            <div className="mono">{(punch && punch.checkOut) || "Not yet"}</div>
          </div>
        </div>

        <div className="form-actions">
          <button className="btn btn-primary" onClick={doCheckIn}>
            <Check size={16} /> Check in
          </button>
          <button className="btn btn-ghost" onClick={doCheckOut}>
            <Check size={16} /> Check out
          </button>
        </div>

        <p className="field-hint">
          These punches are saved directly into the payroll ledger and are visible to the
          admin under "Check-in Log". The admin's Attendance Days page is still where payable
          days for salary slips are set.
        </p>
      </div>

      <div className="panel">
        <div className="panel-head">
          <h3>Recent history</h3>
        </div>
        {history.length === 0 ? (
          <EmptyState text="No punches recorded yet." />
        ) : (
          <table className="ledger-table">
            <thead>
              <tr>
                <th>Date</th>
                <th>Check-in</th>
                <th>Check-out</th>
              </tr>
            </thead>
            <tbody>
              {history.map((p) => (
                <tr key={p.id}>
                  <td>{fmtDate(p.date)}</td>
                  <td className="mono">{p.checkIn || "-"}</td>
                  <td className="mono">{p.checkOut || "-"}</td>
                </tr>
              ))}
            </tbody>
          </table>
        )}
      </div>
    </div>
  );
}

// Standard split used to classify an existing combined earnings figure into heads.
// Basic 50% / HRA 20% / Special Allowance 30% (remainder, so the three always add back exactly).
const GROSS_SPLIT = { basicPct: 0.5, hraPct: 0.2 };

function splitGrossSalary(gross) {
  const g = Math.round(Number(gross) || 0);
  const basic = Math.round(g * GROSS_SPLIT.basicPct);
  const hra = Math.round(g * GROSS_SPLIT.hraPct);
  const special = Math.max(0, g - basic - hra);
  return { basic, hra, special };
}

function EmployeeModal({ employee, onClose, onSave }) {
  const [form, setForm] = useState({ ...employee });
  const set = (k, v) => setForm(f => ({ ...f, [k]: v }));

  const currentFixedTotal = (Number(form.basic) || 0) + (Number(form.hra) || 0) + (Number(form.special) || 0);

  // Splits whatever is ALREADY sitting in Basic + HRA + Special right now — never a
  // separately typed number — so this can never accidentally raise or lower the total.
  function applySplit() {
    const { basic, hra, special } = splitGrossSalary(currentFixedTotal);
    setForm(f => ({ ...f, basic, hra, special }));
  }

  return (
    <div className="modal-backdrop no-print" onMouseDown={onClose}>
      <div className="modal modal-wide" onMouseDown={e => e.stopPropagation()}>
        <div className="modal-head">
          <h3>{employee.name ? "Edit employee" : "Add employee"}</h3>
          <button className="icon-btn" onClick={onClose}><X size={18} /></button>
        </div>
        <div className="modal-body">
          <div className="form-grid">
            <Field label="Employee ID" value={form.empId} onChange={v => set("empId", v)} placeholder="EMP001" />
            <Field label="Full name" value={form.name} onChange={v => set("name", v)} placeholder="Employee name" />
            <Field label="Designation" value={form.designation} onChange={v => set("designation", v)} placeholder="e.g. Accountant" />
            <Field label="Department" value={form.department} onChange={v => set("department", v)} placeholder="e.g. Finance" />
            <Field label="Date of joining" value={form.doj} onChange={v => set("doj", v)} type="date" />
            <Field label="Status" value={form.status} onChange={v => set("status", v)} type="select" options={["Active", "Inactive"]} />
            <Field label="Bank account no." value={form.bankAccount} onChange={v => set("bankAccount", v)} />
            <Field label="IFSC code" value={form.ifsc} onChange={v => set("ifsc", v)} />
            <Field label="PAN" value={form.pan} onChange={v => set("pan", v)} />
            <Field label="UAN (PF)" value={form.uan} onChange={v => set("uan", v)} />
            <Field label="Payment mode" value={form.paymentMode || "Cash"} onChange={v => set("paymentMode", v)} type="select" options={["Cash", "Bank Transfer"]} />
          </div>

          <h4 className="section-title">Monthly earnings (full month)</h4>
          <div className="gross-split-row">
            <div className="gross-split-total">
              Current Basic + HRA + Special total: <strong>₹ {fmtMoney(currentFixedTotal)}</strong>
            </div>
            <button type="button" className="btn btn-ghost" onClick={applySplit} disabled={!currentFixedTotal}>
              Split into Basic/HRA/Special (50/20/30)
            </button>
          </div>
          <p className="field-hint">
            Re-splits the total above as Basic 50% / HRA 20% / Special Allowance 30% — the total itself never changes,
            only how it's divided. Edit the Basic field first if you want to change the actual amount, then split.
          </p>
          <div className="form-grid">
            {EARNING_FIELDS.map(f => (
              <Field key={f.key} label={f.label} value={form[f.key]} onChange={v => set(f.key, v)} type="number" />
            ))}
          </div>

          <h4 className="section-title">Monthly deductions (full month)</h4>
          <div className="form-grid">
            {DEDUCTION_FIELDS.map(f => (
              <Field key={f.key} label={f.label} value={form[f.key]} onChange={v => set(f.key, v)} type="number" />
            ))}
          </div>
        </div>
        <div className="modal-foot">
          <button className="btn btn-ghost" onClick={onClose}>Cancel</button>
          <button className="btn btn-primary" disabled={!form.name.trim()} onClick={() => onSave(form)}>
            <Check size={16} /> Save employee
          </button>
        </div>
      </div>
    </div>
  );
}

function Field({ label, value, onChange, type = "text", placeholder, options }) {
  return (
    <label className="field">
      <span className="field-label">{label}</span>
      {type === "select" ? (
        <select className="input" value={value} onChange={e => onChange(e.target.value)}>
          {options.map(o => <option key={o} value={o}>{o}</option>)}
        </select>
      ) : (
        <input className="input" type={type} value={value ?? ""} placeholder={placeholder}
          onChange={e => onChange(type === "number" ? e.target.value.replace(/[^0-9.]/g, "") : e.target.value)} />
      )}
    </label>
  );
}

function ConfirmModal({ title, body, onCancel, onConfirm, danger = true }) {
  return (
    <div className="modal-backdrop no-print" onMouseDown={onCancel}>
      <div className="modal modal-narrow" onMouseDown={e => e.stopPropagation()}>
        <div className="modal-head"><h3>{title}</h3><button className="icon-btn" onClick={onCancel}><X size={18} /></button></div>
        <div className="modal-body"><p>{body}</p></div>
        <div className="modal-foot">
          <button className="btn btn-ghost" onClick={onCancel}>Cancel</button>
          <button className={`btn ${danger ? "btn-danger" : "btn-primary"}`} onClick={onConfirm}>Confirm</button>
        </div>
      </div>
    </div>
  );
}

