function AttendancePage({ employees, records, setRecords, showToast }) {
  const [month, setMonth] = useState(currentMonth());
  const total = daysInMonth(month);
  const active = employees.filter((e) => e.status !== "Inactive");
  const [rows, setRows] = useState({});

  useEffect(() => {
    const next = {};
    active.forEach((e) => {
      const rec = records.find((r) => r.empId === e.id && r.month === month);
      next[e.id] = rec
        ? {
            payableDays: rec.payableDays,
            leavesTaken: rec.leavesTaken ?? 0,
            paymentDate: rec.paymentDate,
            paymentMode: rec.paymentMode,
          }
        : {
            payableDays: defaultPayableDays(month),
            leavesTaken: 0,
            paymentDate: defaultPaymentDate(month),
            paymentMode: e.paymentMode || "Cash",
          };
    });
    setRows(next);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [month, employees.length]);

  function setRow(empId, patch) {
    setRows((r) => ({
      ...r,
      [empId]: { ...(r[empId] || {}), ...patch },
    }));
  }

  function saveAll() {
    let next = [...records];

    active.forEach((e) => {
      const row = rows[e.id];
      if (!row) return;

      const existingIdx = next.findIndex((r) => r.empId === e.id && r.month === month);

      const rec = {
        id: existingIdx >= 0 ? next[existingIdx].id : uid("rec"),
        empId: e.id,
        month,
        totalDaysInMonth: total,
        payableDays: Math.max(0, Math.min(total, Number(row.payableDays || 0))),
        leavesTaken: Number(row.leavesTaken || 0),
        paymentDate: row.paymentDate || defaultPaymentDate(month),
        paymentMode: row.paymentMode || "Cash",
        status: existingIdx >= 0 ? next[existingIdx].status : "Draft",
        pastImport: existingIdx >= 0 ? next[existingIdx].pastImport : false,
        slipNo: existingIdx >= 0 ? next[existingIdx].slipNo : undefined,
        earningsOverride: existingIdx >= 0 ? next[existingIdx].earningsOverride : undefined,
        deductionsOverride: existingIdx >= 0 ? next[existingIdx].deductionsOverride : undefined,
        generatedAt: existingIdx >= 0 ? next[existingIdx].generatedAt : new Date().toISOString(),
      };

      if (existingIdx >= 0) {
        next[existingIdx] = rec;
      } else {
        next.push(rec);
      }
    });

    setRecords(next);
    showToast(`Attendance saved for ${monthLabel(month)}.`);
  }

  return (
    <div className="page">
      <PageHeader
        eyebrow="Attendance"
        title="Attendance Days"
        subtitle="Set payable days and leaves per employee before generating slips."
        right={<MonthPicker month={month} setMonth={setMonth} />}
      />

      {active.length === 0 ? (
        <EmptyState text="Add employees first from the Employees page." />
      ) : (
        <>
          <table className="ledger-table">
            <thead>
              <tr>
                <th>Employee</th>
                <th>Days in month</th>
                <th>Payable days</th>
                <th>Leaves taken</th>
                <th>Payday</th>
                <th>Payment mode</th>
              </tr>
            </thead>
            <tbody>
              {active.map((e) => {
                const row =
                  rows[e.id] || {
                    payableDays: total,
                    leavesTaken: 0,
                    paymentDate: defaultPaymentDate(month),
                    paymentMode: "Cash",
                  };

                return (
                  <tr key={e.id}>
                    <td>
                      {e.name}
                      <span className="muted">{e.empId}</span>
                    </td>
                    <td className="mono">{total}</td>
                    <td>
                      <input
                        className="input input-sm"
                        type="number"
                        min={0}
                        max={total}
                        value={row.payableDays}
                        onChange={(ev) =>
                          setRow(e.id, { payableDays: ev.target.value })
                        }
                      />
                    </td>
                    <td>
                      <input
                        className="input input-sm"
                        type="number"
                        min={0}
                        value={row.leavesTaken}
                        onChange={(ev) =>
                          setRow(e.id, { leavesTaken: ev.target.value })
                        }
                      />
                    </td>
                    <td>
                      <input
                        className="input input-sm"
                        type="date"
                        value={row.paymentDate}
                        onChange={(ev) =>
                          setRow(e.id, { paymentDate: ev.target.value })
                        }
                      />
                    </td>
                    <td>
                      <select
                        className="input input-sm"
                        style={{ width: 120 }}
                        value={row.paymentMode || "Cash"}
                        onChange={(ev) =>
                          setRow(e.id, { paymentMode: ev.target.value })
                        }
                      >
                        <option>Cash</option>
                        <option>Bank Transfer</option>
                      </select>
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>

          <div className="form-actions">
            <button className="btn btn-primary" onClick={saveAll}>
              <Check size={16} /> Save attendance for {monthLabel(month)}
            </button>
          </div>
        </>
      )}
    </div>
  );
}
