function AttendanceLogPage({ employees, attendanceLog }) {
  const [month, setMonth] = useState(currentMonth());

  const empName = (empId) => {
    const e = employees.find((x) => x.id === empId);
    return e ? `${e.name} (${e.empId || e.id})` : empId;
  };

  const rows = attendanceLog
    .filter((p) => p.date && p.date.slice(0, 7) === month)
    .slice()
    .sort((a, b) => (b.date === a.date ? 0 : b.date.localeCompare(a.date)) || empName(a.empId).localeCompare(empName(b.empId)));

  const presentDaysByEmp = {};
  rows.forEach((p) => {
    if (p.checkIn) {
      presentDaysByEmp[p.empId] = (presentDaysByEmp[p.empId] || 0) + 1;
    }
  });

  const summary = employees
    .filter((e) => presentDaysByEmp[e.id])
    .map((e) => ({ emp: e, days: presentDaysByEmp[e.id] }))
    .sort((a, b) => b.days - a.days);

  return (
    <div className="page">
      <PageHeader
        eyebrow="Attendance"
        title="Check-in Log"
        subtitle="Check-in/check-out punches recorded directly by employees from their portal."
        right={<MonthPicker month={month} setMonth={setMonth} />}
      />

      {summary.length > 0 && (
        <div className="panel">
          <div className="panel-head">
            <h3>Days present this month (by check-in)</h3>
          </div>
          <table className="ledger-table">
            <thead>
              <tr>
                <th>Employee</th>
                <th>Days checked in</th>
              </tr>
            </thead>
            <tbody>
              {summary.map(({ emp, days }) => (
                <tr key={emp.id}>
                  <td>{emp.name}<span className="muted">{emp.empId}</span></td>
                  <td className="mono">{days}</td>
                </tr>
              ))}
            </tbody>
          </table>
          <p className="field-hint">
            This is a reference count from employee-recorded punches. Payable days used for
            salary slips are still set manually on the Attendance Days page.
          </p>
        </div>
      )}

      <div className="panel">
        <div className="panel-head">
          <h3>Punches for {monthLabel(month)}</h3>
        </div>
        {rows.length === 0 ? (
          <EmptyState text="No check-ins recorded for this month yet." />
        ) : (
          <table className="ledger-table">
            <thead>
              <tr>
                <th>Date</th>
                <th>Employee</th>
                <th>Check-in</th>
                <th>Check-out</th>
              </tr>
            </thead>
            <tbody>
              {rows.map((p) => (
                <tr key={p.id}>
                  <td>{fmtDate(p.date)}</td>
                  <td>{empName(p.empId)}</td>
                  <td className="mono">{p.checkIn || "-"}</td>
                  <td className="mono">{p.checkOut || "-"}</td>
                </tr>
              ))}
            </tbody>
          </table>
        )}
      </div>
    </div>
  );
}

function MonthPicker({ month, setMonth }) {
  return <input className="input input-month" type="month" value={month} onChange={e => setMonth(e.target.value)} />;
}

