function BulkPage({ employees, records, setRecords, settings, bumpSlipSeq, showToast }) {
  const [month, setMonth] = useState(currentMonth());
  const active = employees.filter((e) => e.status !== "Inactive");

  const monthRecords = useMemo(
    () => records.filter((r) => r.month === month),
    [records, month]
  );

  function generateAll() {
    if (active.length === 0) return;

    let next = [...records];
    let seq = settings?.nextSlipSeq ?? 1;

    active.forEach((e) => {
      const existingIdx = next.findIndex((r) => r.empId === e.id && r.month === month);
      const base =
        existingIdx >= 0
          ? next[existingIdx]
          : {
              id: uid("rec"),
              empId: e.id,
              month,
              totalDaysInMonth: daysInMonth(month),
              payableDays: defaultPayableDays(month),
              leavesTaken: 0,
              paymentDate: defaultPaymentDate(month),
              paymentMode: e.paymentMode || "Cash",
              status: "Draft",
              pastImport: false,
            };

      let slipNo = base.slipNo;
      if (!slipNo) {
        slipNo = slipNoFor(companyPrefix(settings?.companyName || ""), month, seq);
        seq += 1;
      }

      const rec = {
        ...base,
        status: isMonthInProgress(month) ? "Advance Generated" : "Generated",
        slipNo,
        generatedAt: new Date().toISOString(),
      };

      if (existingIdx >= 0) {
        next[existingIdx] = rec;
      } else {
        next.push(rec);
      }
    });

    setRecords(next);
    if (seq !== (settings?.nextSlipSeq ?? 1)) {
      bumpSlipSeq(seq);
    }

    showToast(`Bulk slips generated for ${monthLabel(month)}.`);
  }

  return (
    <div className="page">
      <PageHeader
        eyebrow="Bulk Generate"
        title="Bulk generate slips"
        subtitle="Generate salary slips for all active employees for a month."
        right={
          <button className="btn btn-primary" onClick={generateAll}>
            <Layers size={16} /> Generate all
          </button>
        }
      />

      <div className="toolbar">
        <MonthPicker month={month} setMonth={setMonth} />
      </div>

      {active.length === 0 ? (
        <EmptyState text="Add employees first from the Employees page." />
      ) : monthRecords.length === 0 ? (
        <EmptyState text={`No slips yet for ${monthLabel(month)}. Click Generate all to create them.`} />
      ) : (
        <table className="ledger-table">
          <thead>
            <tr>
              <th>Employee</th>
              <th>Month</th>
              <th>Payable days</th>
              <th>Net pay</th>
              <th>Status</th>
              <th>Slip no.</th>
            </tr>
          </thead>
          <tbody>
            {monthRecords.map((r) => {
              const emp = employees.find((e) => e.id === r.empId);
              if (!emp) return null;
              const calc = computeSlip(emp, r);

              return (
                <tr key={r.id}>
                  <td>
                    {emp.name}
                    <span className="muted">{emp.empId}</span>
                  </td>
                  <td>{monthLabel(r.month)}</td>
                  <td>
                    {r.payableDays}/{r.totalDaysInMonth}
                  </td>
                  <td className="mono">{fmtMoney(calc.netPay)}</td>
                  <td>
                    <span
                      className={
                        r.status === "Paid"
                          ? "tag tag-green"
                          : r.status === "Advance"
                          ? "tag tag-amber"
                          : "tag tag-blue"
                      }
                    >
                      {r.status}
                    </span>
                  </td>
                  <td className="mono">{r.slipNo || "-"}</td>
                </tr>
              );
            })}
          </tbody>
        </table>
      )}
    </div>
  );
}
