function ImportPage({ employees, records, setRecords, settings, bumpSlipSeq, showToast }) {
  const [input, setInput] = useState("");
  const [parsingErr, setParsingErr] = useState("");
  const [parsed, setParsed] = useState([]);

  function parseCsv() {
    setParsingErr("");
    try {
      const lines = input
        .split(/\r?\n/)
        .map((l) => l.trim())
        .filter(Boolean);

      if (lines.length <= 1) {
        setParsingErr("Paste CSV with a header row and at least one data row.");
        return;
      }

      const [headerLine, ...rows] = lines;
      const headers = headerLine.split(",").map((h) => h.trim());
      const idxEmpId = headers.indexOf("empId");
      const idxMonth = headers.indexOf("month");
      const idxSalary = headers.indexOf("salary");

      if (idxEmpId < 0 || idxMonth < 0 || idxSalary < 0) {
        setParsingErr('CSV must have columns "empId", "month", "salary".');
        return;
      }

      const parsedRows = rows.map((row) => {
        const cols = row.split(",").map((c) => c.trim());
        return {
          empId: cols[idxEmpId],
          month: cols[idxMonth],
          salary: Number(cols[idxSalary] || 0),
        };
      });

      setParsed(parsedRows);
      showToast(`Parsed ${parsedRows.length} rows.`);
    } catch (e) {
      setParsingErr("Could not parse CSV. Check formatting and try again.");
    }
  }

  async function importRows() {
    if (!parsed.length) return;

    let next = [...records];
    let seq = settings?.nextSlipSeq ?? 1;

    parsed.forEach((row) => {
      const emp = employees.find((e) => e.empId === row.empId);
      if (!emp) return;

      const existingIdx = next.findIndex(
        (r) => r.empId === emp.id && r.month === row.month
      );

      const total = daysInMonth(row.month);
      const slipNo = slipNoFor(companyPrefix(settings?.companyName || ""), row.month, seq);
      seq += 1;

      const rec = {
        id: existingIdx >= 0 ? next[existingIdx].id : uid("rec"),
        empId: emp.id,
        month: row.month,
        totalDaysInMonth: total,
        payableDays: total,
        leavesTaken: 0,
        paymentDate: defaultPaymentDate(row.month),
        paymentMode: emp.paymentMode || "Cash",
        status: "Paid",
        pastImport: true,
        slipNo,
        earningsOverride: {
          basic: Number(row.salary || 0),
          hra: 0,
          special: 0,
          incentive: 0,
          overtime: 0,
        },
        deductionsOverride: {
          pf: 0,
          esi: 0,
          pt: 0,
          tds: 0,
          lwp: 0,
          advance: 0,
        },
        generatedAt: new Date().toISOString(),
      };

      if (existingIdx >= 0) {
        next[existingIdx] = rec;
      } else {
        next.push(rec);
      }
    });

    setRecords(next);
    bumpSlipSeq(seq);
    showToast("Imported past months as paid slips.");
  }

  return (
    <div className="page">
      <PageHeader
        eyebrow="Bulk Import Past Months"
        title="Import previous months"
        subtitle="Paste CSV to register past salary months as paid slips."
      />

      <div className="panel">
        <div className="panel-head">
          <h3>Paste CSV</h3>
          <p className="panel-sub">
            Required columns: <strong>empId, month (YYYY-MM), salary</strong>.
          </p>
        </div>

        <textarea
          className="input input-mono"
          rows={10}
          value={input}
          onChange={(e) => setInput(e.target.value)}
          placeholder="empId,month,salary&#10;EMP001,2025-01,25000&#10;EMP002,2025-01,18000"
        />

        {parsingErr && (
          <div className="auth-err">
            <AlertTriangle size={14} /> {parsingErr}
          </div>
        )}

        <div className="form-actions">
          <button className="btn btn-ghost" onClick={parseCsv}>
            Try parsing
          </button>
          <button
            className="btn btn-primary"
            onClick={importRows}
            disabled={!parsed.length}
          >
            <Upload size={16} /> Import as paid slips
          </button>
        </div>
      </div>
    </div>
  );
}
