function RegisterPage({ employees, records, settings }) {
  const [month, setMonth] = useState("");
  const [status, setStatus] = useState("all");

  const filtered = records.filter((r) => {
    if (month && r.month !== month) return false;
    if (status === "paid" && r.status !== "Paid") return false;
    if (status === "advance" && r.status !== "Advance Generated") return false;
    if (status === "generated" && r.status !== "Generated") return false;
    return true;
  });

  return (
    <div className="page">
      <PageHeader
        eyebrow="Previous Slips"
        title="Salary slip register"
        subtitle="Browse and re-print previously generated slips."
      />

      <div className="toolbar">
        <div className="field">
          <span className="field-label">Month</span>
          <MonthPicker month={month || currentMonth()} setMonth={setMonth} />
        </div>
        <div className="field">
          <span className="field-label">Status</span>
          <select
            className="input"
            value={status}
            onChange={(e) => setStatus(e.target.value)}
          >
            <option value="all">All</option>
            <option value="paid">Paid</option>
            <option value="generated">Generated</option>
            <option value="advance">Advance</option>
          </select>
        </div>
      </div>

      {filtered.length === 0 ? (
        <EmptyState text="No salary slips match the current filters." />
      ) : (
        <table className="ledger-table">
          <thead>
            <tr>
              <th>Employee</th>
              <th>Month</th>
              <th>Slip no.</th>
              <th>Net pay</th>
              <th>Status</th>
              <th>Generated at</th>
            </tr>
          </thead>
          <tbody>
            {filtered
              .slice()
              .sort((a, b) => (b.generatedAt || "").localeCompare(a.generatedAt || ""))
              .map((r) => {
                const emp = employees.find((e) => e.id === r.empId);
                if (!emp) return null;
                const calc = computeSlip(emp, r);

                return (
                  <tr key={r.id}>
                    <td>
                      {emp.name}
                      <span className="muted">{emp.empId}</span>
                    </td>
                    <td>{monthLabel(r.month)}</td>
                    <td className="mono">{r.slipNo || "-"}</td>
                    <td className="mono">{fmtMoney(calc.netPay)}</td>
                    <td>
                      <span
                        className={
                          r.status === "Paid"
                            ? "tag tag-green"
                            : r.status === "Advance Generated"
                            ? "tag tag-amber"
                            : "tag tag-blue"
                        }
                      >
                        {r.status}
                      </span>
                    </td>
                    <td>{fmtDate(r.generatedAt)}</td>
                  </tr>
                );
              })}
          </tbody>
        </table>
      )}
    </div>
  );
}
