function SettingsPage({ settings, setSettings, employees, records, setEmployees, setRecords, showToast }) {
  const [form, setForm] = useState({ ...settings });
  const [newPw, setNewPw] = useState("");
  const fileRef = useRef(null);
  const backupFileRef = useRef(null);

  function save() {
    const next = { ...settings, companyName: form.companyName, companyAddress: form.companyAddress, companyPhone: form.companyPhone, companyEmail: form.companyEmail, gstNo: form.gstNo, companyLogo: form.companyLogo };
    if (newPw.trim().length >= 4) next.password = newPw.trim();
    setSettings(next);
    setNewPw("");
    showToast("Settings saved.");
  }

  function handleLogo(e) {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (evt) => setForm(f => ({ ...f, companyLogo: evt.target.result }));
    reader.readAsDataURL(file);
  }

  function downloadBackup() {
    const payload = { exportedAt: new Date().toISOString(), settings, employees, records };
    const blob = new Blob([JSON.stringify(payload, null, 2)], { type: "application/json" });
    const url = URL.createObjectURL(blob);
    const a = document.createElement("a");
    const stamp = new Date().toISOString().slice(0, 10);
    a.href = url;
    a.download = `salary-software-backup-${stamp}.json`;
    document.body.appendChild(a);
    a.click();
    a.remove();
    URL.revokeObjectURL(url);
    showToast("Backup file downloaded.");
  }

  function handleRestoreFile(e) {
    const file = e.target.files?.[0];
    if (!file) return;
    const reader = new FileReader();
    reader.onload = (evt) => {
      try {
        const data = JSON.parse(evt.target.result);
        if (!data || typeof data !== "object") throw new Error("bad file");
        if (!window.confirm("This will replace ALL current employees, slips and settings with the contents of this backup file. Continue?")) return;
        if (data.settings) setSettings(data.settings);
        if (Array.isArray(data.employees)) setEmployees(data.employees);
        if (Array.isArray(data.records)) setRecords(data.records);
        showToast("Backup restored.");
      } catch {
        showToast("Could not read that file — is it a backup exported from this software?", "error");
      }
    };
    reader.readAsText(file);
    e.target.value = "";
  }

  return (
    <div className="page">
      <PageHeader eyebrow="Configuration" title="Settings" subtitle="Company details appear on every salary slip." />
      <div className="panel" style={{ maxWidth: 520 }}>
        <div className="form-grid form-grid-1">
          <Field label="Company name" value={form.companyName} onChange={v => setForm(f => ({ ...f, companyName: v }))} />
          <Field label="Company address" value={form.companyAddress} onChange={v => setForm(f => ({ ...f, companyAddress: v }))} />
          <Field label="Contact phone" value={form.companyPhone} onChange={v => setForm(f => ({ ...f, companyPhone: v }))} />
          <Field label="Contact email" value={form.companyEmail} onChange={v => setForm(f => ({ ...f, companyEmail: v }))} />
          <Field label="GST number" value={form.gstNo} onChange={v => setForm(f => ({ ...f, gstNo: v }))} />

          <div className="field">
            <span className="field-label">Company logo</span>
            <div className="row-gap" style={{ alignItems: "center" }}>
              {form.companyLogo && <img src={form.companyLogo} alt="Logo preview" style={{ width: 44, height: 44, objectFit: "contain", border: "1px solid var(--line)", borderRadius: 4, padding: 4, background: "#fff" }} />}
              <label className="btn btn-ghost file-btn">
                <ImageIcon size={15} /> {form.companyLogo ? "Replace logo" : "Upload logo"}
                <input ref={fileRef} type="file" accept="image/*" onChange={handleLogo} style={{ display: "none" }} />
              </label>
            </div>
          </div>

          <Field label="New admin password (leave blank to keep current)" value={newPw} onChange={setNewPw} type="password" placeholder="••••••" />
        </div>
        <div className="form-actions">
          <button className="btn btn-primary" onClick={save}><Check size={16} /> Save settings</button>
        </div>
      </div>

      <div className="panel" style={{ maxWidth: 520, marginTop: 20 }}>
        <h4 className="section-title" style={{ marginTop: 0 }}>Backup &amp; restore</h4>
        <p className="field-hint">
          All data lives only in this browser on this computer. Download a backup file regularly (e.g. monthly)
          and keep a copy somewhere safe — clearing browser data would otherwise erase everything.
        </p>
        <div className="row-gap">
          <button className="btn btn-ghost" onClick={downloadBackup}><Archive size={16} /> Download backup (.json)</button>
          <label className="btn btn-ghost file-btn">
            <Upload size={16} /> Restore from backup
            <input ref={backupFileRef} type="file" accept="application/json" onChange={handleRestoreFile} style={{ display: "none" }} />
          </label>
        </div>
      </div>
    </div>
  );
}

/* ---------------------------------------------------------------- */
/* Styles — "Ledger" theme                                          */
/* ---------------------------------------------------------------- */

const CSS = `
@import url('https://fonts.googleapis.com/css2?family=Source+Serif+4:opsz,wght@8..60,400;8..60,600;8..60,700&family=Inter:wght@400;500;600;700&family=IBM+Plex+Mono:wght@400;500;600&display=swap');

:root {
  --paper: #F6F4EC;
  --paper-raised: #FFFFFF;
  --ink: #1E2A26;
  --navy: #1F2E3D;
  --navy-2: #28405290;
  --green: #2F6D5C;
  --green-dark: #21503F;
  --red: #A6432E;
  --gold: #B08628;
  --line: #DFD9C6;
  --muted: #7A7566;
}

* { box-sizing: border-box; }

.ledger-root {
  font-family: 'Inter', sans-serif;
  color: var(--ink);
  background: var(--paper);
  min-height: 100vh;
  width: 100%;
}

.boot { padding: 60px; text-align: center; font-family: 'Source Serif 4', serif; font-size: 18px; color: var(--muted); }

.mono { font-family: 'IBM Plex Mono', monospace; }
.right { text-align: right; }
.muted { color: var(--muted); font-size: 12.5px; }

/* Auth */
.auth-wrap { min-height: 100vh; display: flex; align-items: center; justify-content: center; padding: 24px; background:
  radial-gradient(circle at 20% 20%, #EFEADA 0%, var(--paper) 55%); }
.auth-card { background: var(--paper-raised); border: 1px solid var(--line); border-radius: 4px; padding: 40px 36px; width: 380px; position: relative;
  box-shadow: 0 1px 0 var(--line), 0 12px 30px -18px rgba(30,42,38,0.35); }
.auth-title { font-family: 'Source Serif 4', serif; font-size: 26px; margin: 4px 0 6px; color: var(--navy); }
.auth-sub { font-size: 13.5px; color: var(--muted); margin: 0 0 22px; line-height: 1.5; }
.auth-note { font-size: 11.5px; color: var(--muted); margin-top: 14px; line-height: 1.5; }
.btn-plain-link { background: none; border: none; color: var(--muted); font-size: 12px; text-decoration: underline; cursor: pointer; padding: 4px 0; display: block; width: 100%; text-align: center; }
.btn-plain-link:hover { color: var(--navy); }
.auth-reset-box { margin-top: 14px; padding: 12px 14px; border: 1px solid var(--line); border-radius: 4px; background: #FBF7EE; }
.auth-err { display: flex; gap: 6px; align-items: center; color: var(--red); font-size: 12.5px; margin: 4px 0 10px; }

/* Layout */
.app-shell { display: flex; min-height: 100vh; }
.sidebar { width: 236px; background: var(--navy); color: #EDE9DC; display: flex; flex-direction: column; padding: 22px 14px; flex-shrink: 0; }
.sidebar-brand { display: flex; gap: 10px; align-items: center; padding: 0 8px 20px; margin-bottom: 12px; border-bottom: 1px solid #ffffff22; }
.brand-mark { width: 32px; height: 32px; border-radius: 3px; background: var(--gold); color: var(--navy); display: flex; align-items: center; justify-content: center; font-family: 'Source Serif 4', serif; font-weight: 700; font-size: 17px; flex-shrink: 0; }
.brand-name { font-family: 'Source Serif 4', serif; font-size: 14.5px; line-height: 1.25; }
.brand-sub { font-size: 10.5px; color: #C9C2AC; text-transform: uppercase; letter-spacing: 0.06em; margin-top: 2px; }
.nav { display: flex; flex-direction: column; gap: 2px; flex: 1; }
.nav-item { display: flex; align-items: center; gap: 10px; background: none; border: none; color: #D8D3C3; font-family: 'Inter'; font-size: 13.5px; padding: 10px 10px; border-radius: 3px; cursor: pointer; text-align: left; }
.nav-item:hover { background: #ffffff12; color: #fff; }
.nav-item-active { background: #ffffff1c; color: #fff; box-shadow: inset 2px 0 0 var(--gold); }
.nav-logout { margin-top: 10px; border-top: 1px solid #ffffff22; padding-top: 14px; color: #C9C2AC; }

.main-area { flex: 1; padding: 34px 40px 60px; max-width: 1200px; }
.page-header { display: flex; justify-content: space-between; align-items: flex-end; margin-bottom: 22px; gap: 16px; flex-wrap: wrap; }
.eyebrow { font-size: 11px; letter-spacing: 0.08em; text-transform: uppercase; color: var(--green); font-weight: 600; margin-bottom: 4px; }
.page-header h1 { font-family: 'Source Serif 4', serif; font-size: 28px; margin: 0; color: var(--navy); }
.subtitle { color: var(--muted); font-size: 13.5px; margin: 6px 0 0; }

/* Stat cards */
.stat-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 14px; margin-bottom: 28px; }
.stat-card { background: var(--paper-raised); border: 1px solid var(--line); border-radius: 4px; padding: 18px 16px; text-align: left; cursor: pointer; border-top: 3px solid var(--green); }
.stat-card:hover { box-shadow: 0 8px 18px -14px rgba(0,0,0,0.4); }
.stat-value { font-family: 'IBM Plex Mono', monospace; font-size: 22px; color: var(--navy); font-weight: 600; }
.stat-label { font-size: 12px; color: var(--muted); margin-top: 4px; }

/* Panels & tables */
.panel { background: var(--paper-raised); border: 1px solid var(--line); border-radius: 4px; padding: 20px 22px; margin-bottom: 22px; }
.panel-head { display: flex; justify-content: space-between; align-items: center; margin-bottom: 10px; }
.panel-head h3 { font-family: 'Source Serif 4', serif; font-size: 16px; margin: 0; color: var(--navy); }

.ledger-table { width: 100%; border-collapse: collapse; background: var(--paper-raised); border: 1px solid var(--line); border-radius: 4px; overflow: hidden; margin-bottom: 6px; }
.ledger-table th { text-align: left; font-size: 11px; text-transform: uppercase; letter-spacing: 0.05em; color: var(--muted); padding: 10px 14px; border-bottom: 1px solid var(--line); background: #F1EEE2; }
.ledger-table td { padding: 11px 14px; border-bottom: 1px solid var(--line); font-size: 13.5px; }
.ledger-table tr:last-child td { border-bottom: none; }
.ledger-table tr:hover td { background: #FBFAF5; }

.tag { display: inline-block; font-size: 10.5px; font-weight: 600; letter-spacing: 0.03em; padding: 2px 8px; border-radius: 10px; margin-left: 6px; text-transform: uppercase; }
.tag-green { background: #E3EFE8; color: var(--green-dark); }
.tag-blue { background: #E4EAF1; color: #2A4D74; }
.tag-amber { background: #F5EAD3; color: var(--gold); }
.tag-red { background: #F3E1DC; color: var(--red); }
.tag-muted { background: #ECEAE0; color: var(--muted); }

.row-actions { display: flex; gap: 4px; }
.icon-btn { background: none; border: none; cursor: pointer; padding: 6px; border-radius: 4px; color: var(--navy); display: inline-flex; }
.icon-btn:hover { background: #EFEAD9; }
.icon-btn-danger:hover { background: #F3E1DC; color: var(--red); }

.empty-state { padding: 40px 20px; text-align: center; color: var(--muted); border: 1px dashed var(--line); border-radius: 4px; background: var(--paper-raised); font-size: 13.5px; }

/* Toolbar / forms */
.toolbar { display: flex; gap: 16px; align-items: flex-end; margin-bottom: 16px; flex-wrap: wrap; }
.search-box { display: flex; align-items: center; gap: 8px; border: 1px solid var(--line); border-radius: 4px; padding: 8px 12px; background: var(--paper-raised); min-width: 260px; }
.search-box input { border: none; outline: none; background: none; font-size: 13.5px; width: 100%; font-family: 'Inter'; }

.field { display: flex; flex-direction: column; gap: 5px; margin-bottom: 12px; }
.inline-field { margin-bottom: 0; min-width: 200px; }
.field-label { font-size: 11.5px; color: var(--muted); text-transform: uppercase; letter-spacing: 0.04em; }
.input { border: 1px solid var(--line); border-radius: 4px; padding: 9px 11px; font-size: 13.5px; font-family: 'Inter'; background: var(--paper-raised); color: var(--ink); }
.input:focus { outline: 2px solid var(--green); outline-offset: 1px; }
.input-sm { padding: 6px 8px; width: 90px; }
.input-month { width: 170px; }

.form-grid { display: grid; grid-template-columns: 1fr 1fr 1fr; gap: 4px 16px; }
.form-grid-1 { grid-template-columns: 1fr; }
.section-title { font-family: 'Source Serif 4', serif; font-size: 14.5px; color: var(--navy); margin: 18px 0 8px; border-bottom: 1px solid var(--line); padding-bottom: 6px; }
.gross-split-row { display: flex; align-items: center; justify-content: space-between; gap: 12px; background: #F6F4EC; border: 1px solid var(--line); border-radius: 6px; padding: 10px 14px; }
.gross-split-total { font-size: 13px; color: var(--ink); }
.field-hint { font-size: 11.5px; color: var(--muted); margin: 6px 0 12px; }
.form-actions { display: flex; gap: 10px; margin-top: 14px; }
.row-gap { display: flex; gap: 10px; }
.hint { font-size: 12px; color: var(--muted); margin-top: 8px; }

/* Buttons */
.btn { display: inline-flex; align-items: center; gap: 7px; font-family: 'Inter'; font-size: 13px; font-weight: 600; padding: 9px 16px; border-radius: 4px; border: 1px solid transparent; cursor: pointer; }
.btn-primary { background: var(--green); color: #fff; }
.btn-primary:hover { background: var(--green-dark); }
.btn-primary:disabled { opacity: 0.45; cursor: not-allowed; }
.btn-ghost { background: var(--paper-raised); color: var(--navy); border-color: var(--line); }
.btn-ghost:hover { background: #F1EEE2; }
.btn-danger { background: var(--red); color: #fff; }
.btn-block { width: 100%; justify-content: center; margin-top: 6px; }
.file-btn { cursor: pointer; }

/* Modal */
.modal-backdrop { position: fixed; inset: 0; background: rgba(20,26,24,0.45); display: flex; align-items: center; justify-content: center; z-index: 50; padding: 20px; }
.modal { background: var(--paper-raised); border-radius: 5px; width: 100%; max-height: 88vh; display: flex; flex-direction: column; }
.modal-wide { max-width: 720px; }
.modal-narrow { max-width: 420px; }
.modal-head { display: flex; justify-content: space-between; align-items: center; padding: 18px 22px; border-bottom: 1px solid var(--line); }
.modal-head h3 { font-family: 'Source Serif 4', serif; margin: 0; font-size: 17px; color: var(--navy); }
.modal-body { padding: 20px 22px; overflow-y: auto; }
.modal-foot { padding: 16px 22px; border-top: 1px solid var(--line); display: flex; justify-content: flex-end; gap: 10px; }

/* Stamp */
.stamp { display: inline-flex; align-items: center; justify-content: center; border: 2px dashed currentColor; border-radius: 50%; width: 84px; height: 84px; font-family: 'IBM Plex Mono', monospace; font-size: 11px; font-weight: 700; letter-spacing: 0.05em; transform: rotate(-9deg); text-align: center; padding: 6px; }
.stamp-static { position: absolute; top: 22px; right: 22px; color: var(--gold); width: 64px; height: 64px; font-size: 9.5px; }
.stamp-green { color: var(--green-dark); }
.stamp-navy { color: var(--navy); }
.stamp-amber { color: var(--gold); }

/* Toast */
.toast { position: fixed; bottom: 24px; right: 24px; background: var(--navy); color: #fff; padding: 12px 18px; border-radius: 4px; font-size: 13px; box-shadow: 0 10px 24px -10px rgba(0,0,0,0.5); z-index: 100; animation: toastIn 0.2s ease; }
.toast-err { background: var(--red); }
@keyframes toastIn { from { opacity: 0; transform: translateY(6px);} to { opacity:1; transform: translateY(0);} }

/* Slip document */
.print-area { }
.slip { background: var(--paper-raised); border: 1px solid var(--line); border-radius: 5px; padding: 30px 34px; max-width: 780px; position: relative; }
.slip-head { display: flex; justify-content: space-between; align-items: flex-start; margin-bottom: 6px; }
.slip-head-centered { justify-content: center; }
.slip-company { display: flex; gap: 10px; align-items: flex-start; color: var(--navy); }
.slip-company-centered { flex-direction: column; align-items: center; text-align: center; gap: 6px; }
.slip-company-centered .slip-company-addr { max-width: 480px; margin-left: auto; margin-right: auto; }
.slip-company-name { font-family: 'Source Serif 4', serif; font-size: 19px; color: var(--navy); }
.slip-company-addr { font-size: 11.5px; color: var(--muted); margin-top: 2px; max-width: 360px; line-height: 1.4; }
.slip-logo { width: 46px; height: 46px; object-fit: contain; flex-shrink: 0; }
.slip-titlebar { display: flex; justify-content: space-between; align-items: baseline; border-bottom: 1px solid var(--line); padding-bottom: 14px; margin-bottom: 18px; flex-wrap: wrap; gap: 6px; }
.slip-no { font-size: 12px; color: var(--muted); }
.slip-title { font-family: 'Source Serif 4', serif; font-size: 15px; color: var(--green-dark); }
.print-only-block { display: none; }
@media print { .print-only-block { display: block; } }
.slip-meta-grid { display: grid; grid-template-columns: repeat(5, 1fr); gap: 14px 10px; margin-bottom: 22px; }
.meta-label { font-size: 10px; text-transform: uppercase; letter-spacing: 0.04em; color: var(--muted); }
.meta-value { font-size: 13px; margin-top: 2px; font-weight: 500; }
.slip-columns { display: grid; grid-template-columns: 1fr 1fr; gap: 24px; margin-bottom: 6px; }
.slip-col-title { font-size: 11px; text-transform: uppercase; letter-spacing: 0.05em; color: var(--green-dark); font-weight: 700; margin-bottom: 8px; }
.slip-table { width: 100%; border-collapse: collapse; }
.slip-table td { padding: 7px 0; border-bottom: 1px solid var(--line); font-size: 13px; }
.slip-total-row td { font-weight: 700; border-top: 1px solid var(--ink); border-bottom: none; padding-top: 9px; }
.slip-net { display: flex; justify-content: space-between; align-items: center; background: #EEF3EF; border: 1px solid var(--green); border-radius: 4px; padding: 12px 16px; margin-top: 18px; font-family: 'Source Serif 4', serif; font-size: 17px; color: var(--green-dark); font-weight: 700; }
.slip-net-words { font-size: 12.5px; color: var(--ink); margin-top: 8px; font-style: italic; }
.slip-signature-row { display: flex; justify-content: space-between; gap: 40px; margin-top: 48px; }
.slip-signature-row-single { justify-content: flex-end; }
.slip-signature-row-single .slip-signature-box { flex: 0 0 240px; }
.slip-signature-box { flex: 1; text-align: center; }
.slip-signature-line { border-top: 1px solid var(--ink); margin: 0 8px 6px; height: 36px; }
.slip-signature-label { font-size: 11.5px; color: var(--muted); letter-spacing: 0.02em; }
.slip-footnote { font-size: 10.5px; color: var(--muted); margin-top: 14px; }
.page-break { page-break-before: always; margin-top: 24px; }

/* Print rules */
@media print {
  body * { visibility: hidden; }
  .print-area, .print-area * { visibility: visible; }
  .print-area { position: absolute; left: 0; top: 0; width: 100%; }
  .no-print { display: none !important; }
  .slip { border: none; box-shadow: none; }
}
`;


